def image(name,alt,base='',eager=False,cls=''):
 return f'<img class="{cls}" src="{base}assets/{name}-1400.webp" srcset="{base}assets/{name}-640.webp 640w, {base}assets/{name}-1400.webp 1400w" sizes="(max-width: 700px) 100vw, 60vw" width="1400" height="1000" alt="{esc(alt)}" {"fetchpriority=high" if eager else "loading=lazy"} decoding="async">'

