def document(title,desc,body,base='',path='index.html'):
 url=C['origin']+'/'+path
 structured=json.dumps({'@context':'https://schema.org','@type':'LocalBusiness','name':C['company'],'telephone':C['phone_e164'],'email':C['email'],'url':C['origin'],'sameAs':[C['instagram']],'address':{'@type':'PostalAddress','addressLocality':'Los Garres','addressRegion':'Murcia'}},ensure_ascii=False).replace('</','<\\/')
 return f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)}</title><meta name="description" content="{esc(desc)}"><meta name="theme-color" content="#e3222a"><meta property="og:type" content="website"><meta property="og:locale" content="es_ES"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(desc)}"><meta property="og:url" content="{url}"><script type="application/ld+json">{structured}</script><link rel="icon" href="{base}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{base}assets/styles.css"><script src="{base}assets/app.js" defer></script></head><body>{header(base)}<main id="contenido">{body}</main>{footer(base)}</body></html>'''

